begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.ut(t text) returns uuid language sql immutable as $$select md5('users-team-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.ut(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.ut(x),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',x||'-ut@example.invalid',now(),now(),now() from unnest(array['owner','member','leader','plain']) x;
insert into public.organizations(id,name,slug,status) values(pg_temp.ut('org'),'Igreja fictícia usuários','users-team-test','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.ut('a'),pg_temp.ut('org'),'Sede','sede','headquarters');
insert into public.organization_units(id,organization_id,name,slug,unit_type,parent_unit_id) values(pg_temp.ut('b'),pg_temp.ut('org'),'Filial','filial','campus',pg_temp.ut('a'));
insert into public.organization_memberships(id,organization_id,user_id,role,status,default_unit_id) select pg_temp.ut(x||'-m'),pg_temp.ut('org'),pg_temp.ut(x),case when x='owner' then 'owner' else 'member' end::public.membership_role,'active',pg_temp.ut('a') from unnest(array['owner','member','leader','plain']) x;
insert into public.people(id,organization_id,unit_id,full_name,status,auth_user_id) select pg_temp.ut(x||'-p'),pg_temp.ut('org'),pg_temp.ut('a'),x||' pessoa fictícia','active',pg_temp.ut(x) from unnest(array['member','leader','plain']) x;
select ok(not private.membership_is_team(pg_temp.ut('member-m')),'membro sem função não é equipe');
set local role authenticated;
select pg_temp.actor('owner');
select lives_ok($$select public.permission_admin(pg_temp.ut('org'),'set',jsonb_build_object('membership',pg_temp.ut('member-m'),'permission','people.members','unit',pg_temp.ut('b'),'includeChildren',false,'actions',jsonb_build_array('view')))$$,'concede permissão numa igreja');
reset role;
select ok(private.membership_is_team(pg_temp.ut('member-m')),'com permissão vira equipe');
select is((select count(*)::int from public.membership_unit_access where membership_id=pg_temp.ut('member-m') and unit_id=pg_temp.ut('b')),1,'acesso à igreja criado junto com a permissão');
select ok((select (u->>'team')::boolean from jsonb_array_elements(public.staff_directory(pg_temp.ut('org'))->'users') u where u->>'id'=pg_temp.ut('member-m')::text),'lista de usuários marca equipe') ;
set local role authenticated;
select pg_temp.actor('owner');
select throws_ok($$select public.permission_admin(pg_temp.ut('org'),'set',jsonb_build_object('membership',pg_temp.ut('member-m'),'permission','people.import','unit','','includeChildren',true,'actions',jsonb_build_array('view')))$$,'22023','invalid_actions','ação que a seção não tem é recusada');
select throws_ok($$select public.permission_admin(pg_temp.ut('org'),'save_custom_template','{"name":"Recepção","items":{"people.visitors":["view","fly"]}}')$$,'22023','invalid_template','modelo com ação inválida é recusado');
select ok(public.permission_admin(pg_temp.ut('org'),'save_custom_template','{"name":"Recepção","description":"Visitantes e Kids","items":{"people.visitors":["view","create"],"people.members":["view"]}}')->>'id' is not null,'cria modelo personalizado');
select is(jsonb_array_length(public.permission_admin(pg_temp.ut('org'),'custom_templates','{}')->'items'),1,'lista modelos da igreja');
select is(jsonb_array_length(public.permission_admin(pg_temp.ut('org'),'apply_custom_template',jsonb_build_object('membership',pg_temp.ut('plain-m'),'template',public.permission_admin(pg_temp.ut('org'),'custom_templates','{}')->'items'->0->>'id','units',jsonb_build_array(pg_temp.ut('a'),pg_temp.ut('b'))))->'grants'),4,'modelo aplicado em duas igrejas');
select pg_temp.actor('member');
select throws_ok($$select public.permission_admin(pg_temp.ut('org'),'custom_templates','{}')$$,'42501','permission_admin_denied','membro não vê modelos');
select throws_ok($$select public.people_groups(pg_temp.ut('org'),'save','{"name":"Pastores"}')$$,'42501','people_group_denied','membro não cria grupos');
select pg_temp.actor('owner');
select ok(public.people_groups(pg_temp.ut('org'),'save','{"name":"Pastores","color":"#1b4a3b"}')->>'id' is not null,'cria grupo Pastores');
select lives_ok($$select public.people_groups(pg_temp.ut('org'),'set_person',jsonb_build_object('person',pg_temp.ut('leader-p'),'groups',jsonb_build_array(public.people_groups(pg_temp.ut('org'),'list')->'items'->0->>'id'))) $$,'coloca a pessoa no grupo');
select is((public.people_groups(pg_temp.ut('org'),'list')->'items'->0->>'count'),'1','grupo com um membro');
reset role;
select ok(private.membership_is_team(pg_temp.ut('leader-m')),'quem está num grupo vira equipe');
select lives_ok($$select private.push_audience_check(jsonb_build_object('peopleGroups',jsonb_build_array(pg_temp.ut('x'))))$$,'push aceita filtro por grupo');
select throws_ok($$select private.push_audience_check('{"peopleGroups":["x"]}')$$,'22023','invalid_push_audience','grupo inválido recusado');
select * from finish();
rollback;
